package com.nivor.focus;
import com.nivor.common.entity.AuditedEntity;import com.nivor.task.Task;import com.nivor.user.User;import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="focus_sessions",indexes=@Index(name="idx_focus_user_started",columnList="user_id,started_at"))public class FocusSession extends AuditedEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="task_id")private Task task;@Column(nullable=false)private Integer durationSeconds;@Column(nullable=false)private Integer elapsedSeconds=0;@Column(nullable=false)private LocalDateTime startedAt;private LocalDateTime pausedAt;private LocalDateTime endedAt;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private FocusStatus status=FocusStatus.IN_PROGRESS;protected FocusSession(){}public User getUser(){return user;}public void setUser(User v){user=v;}public Task getTask(){return task;}public void setTask(Task v){task=v;}public Integer getDurationSeconds(){return durationSeconds;}public void setDurationSeconds(Integer v){durationSeconds=v;}public Integer getElapsedSeconds(){return elapsedSeconds==null?0:elapsedSeconds;}public void setElapsedSeconds(Integer v){elapsedSeconds=v;}public LocalDateTime getPausedAt(){return pausedAt;}public void setPausedAt(LocalDateTime v){pausedAt=v;}public LocalDateTime getStartedAt(){return startedAt;}public void setStartedAt(LocalDateTime v){startedAt=v;}public LocalDateTime getEndedAt(){return endedAt;}public void setEndedAt(LocalDateTime v){endedAt=v;}public FocusStatus getStatus(){return status;}public void setStatus(FocusStatus v){status=v;}}
